-- Function: public.fn_get_child_care_events_by_child_and_date
-- Backup generated on 2026-10-25 20:33:08

CREATE OR REPLACE FUNCTION public.fn_get_child_care_events_by_child_and_date(p_tenant_id uuid, p_child_id uuid, p_date date)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, child_id uuid, event_type character varying, event_time timestamp with time zone, diaper_condition character varying, skin_observation character varying, meal_type character varying, food_offered character varying, amount_consumed character varying, fluid_oz numeric, rest_status character varying, toileting_activity character varying, hygiene_type character varying, comfort_mood character varying, notes text, parent_visible boolean, recorded_by_user_id uuid, recorded_by_name character varying, correction_reason text, is_corrected boolean, created_at timestamp with time zone, updated_at timestamp with time zone, child_name text, classroom_name character varying)  LANGUAGE sql  STABLE AS $function$     SELECT e.id, e.tenant_id, e.organization_id, e.branch_id, e.classroom_id, e.child_id,            e.event_type, e.event_time, e.diaper_condition, e.skin_observation,            e.meal_type, e.food_offered, e.amount_consumed, e.fluid_oz,            e.rest_status, e.toileting_activity, e.hygiene_type, e.comfort_mood,            e.notes, e.parent_visible, e.recorded_by_user_id, e.recorded_by_name,            e.correction_reason, e.is_corrected, e.created_at, e.updated_at,            CONCAT(c.first_name, ' ', c.last_name) AS child_name,            cl.name AS classroom_name     FROM child_care_events e     JOIN children c ON e.child_id = c.id     LEFT JOIN classrooms cl ON e.classroom_id = cl.id     WHERE e.tenant_id = p_tenant_id        AND e.child_id = p_child_id       AND (e.event_time::date = p_date OR (e.event_time AT TIME ZONE 'America/New_York')::date = p_date)     ORDER BY e.event_time ASC; $function$ ;
